import { ChevronRightIcon } from "lucide-react"

import { cn } from "@/lib/utils"

/** One-line trail; every crumb before the last calls `onNavigate`, the last is the current place. */
export function Breadcrumb({
  trail,
  onNavigate,
}: {
  trail: string[]
  onNavigate?: (index: number) => void
}) {
  return (
    <nav aria-label="Breadcrumb" className="flex h-8 items-center border-b px-3 text-xs">
      <ol className="flex min-w-0 items-center gap-1">
        {trail.map((crumb, index) => {
          const last = index === trail.length - 1
          return (
            <li key={index} className={cn("flex items-center gap-1", last ? "min-w-0" : "shrink-0")}>
              {last || !onNavigate ? (
                <span
                  aria-current={last ? "page" : undefined}
                  className={cn("truncate", last ? "font-medium" : "text-muted-foreground")}
                >
                  {crumb}
                </span>
              ) : (
                <button
                  type="button"
                  onClick={() => onNavigate(index)}
                  className="truncate rounded-sm text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                >
                  {crumb}
                </button>
              )}
              {last ? null : (
                <ChevronRightIcon className="size-3 shrink-0 text-muted-foreground" aria-hidden />
              )}
            </li>
          )
        })}
      </ol>
    </nav>
  )
}

import { useEffect, useId, useMemo, useRef, useState, type ReactNode } from "react"
import { useHotkeys } from "react-hotkeys-hook"
import { ArrowUpRightIcon, CheckIcon, PlusIcon } from "lucide-react"

import { EmptyState } from "@/components/mini/states"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"

import type { CollectionDef, DocRecord, FieldDef, PropValue } from "./types"

function Cell({ field, value }: { field: FieldDef; value: PropValue }): ReactNode {
  if (value === null || value === "" || value === false) return null
  if (field.type === "checkbox") {
    return (
      <>
        <CheckIcon className="size-3.5" aria-hidden />
        <span className="sr-only">Yes</span>
      </>
    )
  }
  if (field.type === "select") return <Badge variant="secondary">{String(value)}</Badge>
  return String(value)
}

function matches(record: DocRecord, query: string) {
  const needle = query.trim().toLowerCase()
  if (!needle) return true
  return (
    record.title.toLowerCase().includes(needle) ||
    Object.values(record.props).some((value) => value !== null && String(value).toLowerCase().includes(needle))
  )
}

/**
 * One collection as a numbered grid with a search box and an Add button. The grid is a single tab stop:
 * while it has focus, arrows or j/k move the selection, Enter opens the selected row and n adds a record.
 */
export function CollectionBlock<T extends DocRecord>({
  def,
  records,
  selectedId,
  onSelect,
  onOpen,
  onAdd,
}: {
  def: CollectionDef
  records: T[]
  selectedId?: string
  onSelect: (id: string) => void
  onOpen: (id: string) => void
  onAdd: () => void
}) {
  const uid = useId()
  const [query, setQuery] = useState("")
  const rows = useMemo(() => records.filter((record) => matches(record, query)), [records, query])
  const selectedIndex = rows.findIndex((row) => row.id === selectedId)
  const rowDomId = (id: string) => `${uid}-${id}`

  const move = (delta: 1 | -1) => {
    if (rows.length === 0) return
    const next = selectedIndex < 0 ? (delta > 0 ? 0 : rows.length - 1) : Math.min(rows.length - 1, Math.max(0, selectedIndex + delta))
    onSelect(rows[next].id)
  }

  const gridRef = useHotkeys<HTMLTableElement>(
    ["down", "up", "j", "k", "enter", "n"],
    (event) => {
      switch (event.key) {
        case "ArrowDown":
        case "j":
          return move(1)
        case "ArrowUp":
        case "k":
          return move(-1)
        case "Enter":
          if (selectedIndex >= 0) onOpen(rows[selectedIndex].id)
          return
        case "n":
          return onAdd()
      }
    },
    { preventDefault: true, ignoreEventWhen: (event) => event.target !== event.currentTarget }
  )

  const previous = useRef(selectedId)
  useEffect(() => {
    if (selectedId && previous.current !== selectedId) {
      document.getElementById(`${uid}-${selectedId}`)?.scrollIntoView({ block: "nearest" })
    }
    previous.current = selectedId
  }, [selectedId, uid])

  return (
    <section aria-label={def.name} className="my-4">
      <div className="flex h-[30px] items-center gap-2">
        <h2 data-mini="group-header" className="min-w-0 flex-1 truncate text-sm font-semibold">{def.name}</h2>
        <Input
          type="search"
          aria-label={`Search ${def.name}`}
          placeholder="Search"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          className="h-7 w-36 text-xs md:text-xs"
        />
        <Button variant="outline" size="sm" onClick={onAdd} aria-label={`Add record to ${def.name}`}>
          <PlusIcon aria-hidden /> Add
        </Button>
      </div>

      <div className="mt-1 max-h-[450px] overflow-auto rounded-md border has-[table:focus-visible]:ring-3 has-[table:focus-visible]:ring-ring/50">
        <table
          ref={gridRef}
          role="grid"
          tabIndex={0}
          aria-label={def.name}
          aria-activedescendant={selectedIndex >= 0 ? rowDomId(selectedId!) : undefined}
          data-collection-id={def.id}
          className="w-max min-w-full border-collapse text-sm outline-none"
        >
          <thead className="sticky top-0 z-10 bg-background text-xs text-muted-foreground">
            <tr role="row" className="h-[30px] border-b">
              <th role="columnheader" scope="col" className="w-10 px-2 text-right font-normal">
                #
              </th>
              <th role="columnheader" scope="col" className="min-w-40 px-2 text-left font-normal">
                Title
              </th>
              {def.fields.map((field) => (
                <th
                  key={field.key}
                  role="columnheader"
                  scope="col"
                  className={cn("min-w-28 px-2 font-normal", field.type === "number" ? "text-right" : "text-left")}
                >
                  {field.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row, index) => (
              <tr
                key={row.id}
                id={rowDomId(row.id)}
                role="row"
                data-mini="row"
                aria-selected={row.id === selectedId}
                onClick={() => onSelect(row.id)}
                className="h-[30px] border-b last:border-b-0 hover:bg-muted/50 aria-selected:bg-accent"
              >
                <td role="gridcell" data-mini="cell" className="px-2 text-right text-xs text-muted-foreground tabular-nums">
                  {index + 1}
                </td>
                <td role="gridcell" data-mini="cell" className="max-w-56 px-2">
                  <div className="flex items-center gap-1">
                    <span className="min-w-0 flex-1 truncate" title={row.title}>
                      {row.title}
                    </span>
                    <Button
                      variant="ghost"
                      size="icon-xs"
                      tabIndex={-1}
                      aria-label={`Open ${row.title}`}
                      onClick={(event) => {
                        event.stopPropagation()
                        onSelect(row.id)
                        onOpen(row.id)
                      }}
                    >
                      <ArrowUpRightIcon aria-hidden />
                    </Button>
                  </div>
                </td>
                {def.fields.map((field) => (
                  <td
                    key={field.key}
                    role="gridcell"
                    data-mini="cell"
                    className={cn("px-2 whitespace-nowrap", field.type === "number" && "text-right tabular-nums")}
                  >
                    <Cell field={field} value={row.props[field.key] ?? null} />
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {records.length === 0 ? (
        <EmptyState
          title="No records"
          action={
            <Button size="sm" onClick={onAdd}>
              <PlusIcon aria-hidden /> Add record
            </Button>
          }
        />
      ) : rows.length === 0 ? (
        <EmptyState title="No matches" description={`Nothing in ${def.name} matches "${query.trim()}".`} />
      ) : null}
    </section>
  )
}

import { useState } from "react"
import { toast } from "sonner"

import { ErrorState, LoadingState } from "@/components/mini/states"
import { Button } from "@/components/ui/button"
import { useCollection } from "@/lib/mini/store"

import { DocCollections } from "./doc-collections"
import type { CollectionDef, DocPage, DocRecord } from "./types"

type Preview = "live" | "empty" | "loading" | "error"
const PREVIEWS: Preview[] = ["live", "empty", "loading", "error"]

const PAGE_ID = "reading-list"

const books: CollectionDef = {
  id: "books",
  name: "Books",
  fields: [
    { key: "status", label: "Status", type: "select", options: ["Want to read", "Reading", "Finished"] },
    { key: "rating", label: "Rating", type: "number" },
    { key: "started", label: "Started", type: "date" },
    { key: "owned", label: "Owned", type: "checkbox" },
  ],
}

const quotes: CollectionDef = {
  id: "quotes",
  name: "Quotes",
  fields: [
    { key: "source", label: "Source", type: "text" },
    { key: "page", label: "Page", type: "number" },
  ],
}

const seedPage: DocPage = {
  id: PAGE_ID,
  title: "Reading List",
  collections: [books, quotes],
  blocks: [
    {
      id: "intro",
      kind: "text",
      text: "A running log of what I read this year. Each book keeps a short review in its notes.",
    },
    { id: "books-block", kind: "collection", collectionId: books.id },
    { id: "between", kind: "text", text: "Lines worth keeping, with where they came from." },
    { id: "quotes-block", kind: "collection", collectionId: quotes.id },
  ],
}

function book(
  n: number,
  title: string,
  status: string,
  rating: number | null,
  started: string | null,
  owned: boolean,
  body = ""
): DocRecord {
  return { id: `book-${n}`, title, collectionId: books.id, props: { status, rating, started, owned }, body }
}

function quote(n: number, title: string, source: string, page: number, body = ""): DocRecord {
  return { id: `quote-${n}`, title, collectionId: quotes.id, props: { source, page }, body }
}

const seedRecords: DocRecord[] = [
  book(1, "Dune", "Finished", 4, "2026-01-04", true, "Slow first hundred pages, then it does not let go."),
  book(2, "Deep Work", "Reading", null, "2026-03-10", true, "Good argument, repetitive examples."),
  book(3, "The Left Hand of Darkness", "Finished", 5, "2026-02-01", false, "The journey across the ice is the whole book."),
  book(4, "Braiding Sweetgrass", "Reading", null, "2026-04-02", true),
  book(5, "Piranesi", "Finished", 5, "2026-01-20", false, "Short and strange. Read it in one sitting."),
  book(6, "The Overstory", "Want to read", null, null, false),
  book(7, "A Pattern Language", "Reading", 3, "2026-03-28", true, "A book to dip into, not to read straight through."),
  book(8, "Flatland", "Finished", 3, "2026-02-18", false),
  book(
    9,
    "An Exceptionally Long Working Title for a Book About Everything That Happened Before, During and After the Great Reorganization of the Municipal Archive",
    "Want to read",
    null,
    null,
    false
  ),
  book(10, "Gödel, Escher, Bach", "Want to read", null, null, true),
  book(11, "The Dispossessed", "Finished", 4, "2026-05-06", true, "Both planets feel lived in."),
  book(12, "Seeing Like a State", "Reading", null, "2026-06-12", false),
]

const seedQuotes: DocRecord[] = [
  quote(1, "The mystery of life isn't a problem to solve", "Dune", 12),
  quote(2, "Attention is the rarest form of generosity", "Deep Work", 88, "Paraphrased from memory; check the exact wording."),
  quote(3, "It is good to have an end to journey toward", "The Left Hand of Darkness", 220),
  quote(4, "The house is all the world", "Piranesi", 41),
  quote(5, "Every pattern is a relationship between parts", "A Pattern Language", 9),
]

const initialRecords = [...seedRecords, ...seedQuotes]

type Journal = {
  page: DocPage
  onPageChange: (page: DocPage) => void
  records: DocRecord[]
  onAdd: (collectionId: string) => Promise<DocRecord>
  onUpdate: (id: string, patch: Partial<DocRecord>) => Promise<void>
  onRemove: (id: string) => Promise<void>
}

function newRecord(collectionId: string): DocRecord {
  return { id: crypto.randomUUID(), title: "Untitled", collectionId, props: {}, body: "" }
}

function useStoredJournal(): Journal & { status: "loading" | "ready" | "error"; error?: Error } {
  const pages = useCollection<DocPage>("doc-collections-demo-page", [seedPage])
  const records = useCollection<DocRecord>("doc-collections-demo", initialRecords)
  const page = pages.items.find((item) => item.id === PAGE_ID) ?? seedPage

  const status = pages.status === "error" || records.status === "error" ? "error" : pages.status === "loading" || records.status === "loading" ? "loading" : "ready"

  return {
    status,
    error: pages.error ?? records.error,
    page,
    onPageChange: (next) => {
      pages.update(PAGE_ID, next).catch((cause: unknown) => {
        toast.error(`Could not save: ${cause instanceof Error ? cause.message : String(cause)}`)
      })
    },
    records: records.items,
    onAdd: async (collectionId) => {
      const created = newRecord(collectionId)
      await records.add(created)
      return created
    },
    onUpdate: records.update,
    onRemove: records.remove,
  }
}

// the empty preview must not touch the stored journal, so it edits its own in-memory copy
function useScratchJournal(): Journal {
  const [page, setPage] = useState<DocPage>({ id: "scratch", title: "Reading List", blocks: [], collections: [] })
  const [records, setRecords] = useState<DocRecord[]>([])
  return {
    page,
    onPageChange: setPage,
    records,
    onAdd: async (collectionId) => {
      const created = newRecord(collectionId)
      setRecords((current) => [...current, created])
      return created
    },
    onUpdate: async (id, patch) => setRecords((current) => current.map((r) => (r.id === id ? { ...r, ...patch } : r))),
    onRemove: async (id) => setRecords((current) => current.filter((r) => r.id !== id)),
  }
}

function PreviewSwitch({ value, onChange }: { value: Preview; onChange: (value: Preview) => void }) {
  return (
    <div role="group" aria-label="Preview state" className="flex h-9 shrink-0 items-center justify-end gap-1 border-b px-3">
      <span className="mr-1 text-xs text-muted-foreground">Preview state</span>
      {PREVIEWS.map((state) => (
        <Button
          key={state}
          size="xs"
          variant={state === value ? "secondary" : "ghost"}
          aria-pressed={state === value}
          onClick={() => onChange(state)}
        >
          {state}
        </Button>
      ))}
    </div>
  )
}

export default function Demo() {
  const [preview, setPreview] = useState<Preview>("live")
  const stored = useStoredJournal()
  const scratch = useScratchJournal()

  const shown: Preview = preview !== "live" ? preview : stored.status === "ready" ? "live" : stored.status
  const journal = preview === "empty" ? scratch : stored

  let body
  if (shown === "loading" || shown === "error") {
    body = (
      <>
        <div className="flex h-8 items-center border-b px-3 text-xs font-medium">{stored.page.title}</div>
        {shown === "loading" ? (
          <LoadingState label="Loading document" />
        ) : (
          <ErrorState
            error={stored.error ?? new Error("Could not read the saved document.")}
            onRetry={() => (preview === "live" ? window.location.reload() : setPreview("live"))}
          />
        )}
      </>
    )
  } else {
    body = (
      <DocCollections
        key={shown}
        page={journal.page}
        onPageChange={journal.onPageChange}
        records={journal.records}
        onAdd={journal.onAdd}
        onUpdate={journal.onUpdate}
        onRemove={journal.onRemove}
      />
    )
  }

  return (
    <div className="flex h-full min-h-0 flex-col">
      <PreviewSwitch value={preview} onChange={setPreview} />
      <div className="min-h-0 flex-1 overflow-auto">{body}</div>
    </div>
  )
}

import { useEffect, useLayoutEffect, useRef, useState } from "react"
import { PlusIcon, Trash2Icon } from "lucide-react"
import { toast } from "sonner"

import { EmptyState } from "@/components/mini/states"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"

import { Breadcrumb } from "./breadcrumb"
import { CollectionBlock } from "./collection-block"
import { columnClass } from "./column"
import { RecordPage } from "./record-page"
import type { DocPage, DocRecord } from "./types"
import { useDraft } from "./use-draft"

function scrollParentOf(element: HTMLElement | null): HTMLElement | null {
  for (let node = element?.parentElement; node; node = node.parentElement) {
    const overflow = getComputedStyle(node).overflowY
    if ((overflow === "auto" || overflow === "scroll") && node.scrollHeight > node.clientHeight) return node
  }
  return null
}

function reportSaveError(cause: unknown) {
  toast.error(`Could not save: ${cause instanceof Error ? cause.message : String(cause)}`)
}

function TextBlock({ text, onCommit }: { text: string; onCommit: (text: string) => void }) {
  const [draft, setDraft] = useDraft(text)
  return (
    <Textarea
      aria-label="Text block"
      placeholder="Write something"
      value={draft}
      onChange={(event) => setDraft(event.target.value)}
      onBlur={() => {
        if (draft !== text) onCommit(draft)
      }}
      className="my-1 min-h-8 resize-none border-transparent px-1.5 py-1 shadow-none hover:border-input focus-visible:border-ring dark:bg-transparent"
    />
  )
}

function PageTitle({ title, onCommit }: { title: string; onCommit: (title: string) => void }) {
  const [draft, setDraft] = useDraft(title)
  return (
    <Input
      aria-label="Page title"
      data-mini="title"
      value={draft}
      onChange={(event) => setDraft(event.target.value)}
      onBlur={() => {
        const next = draft.trim()
        if (next === "" || next === title) setDraft(title)
        else onCommit(next)
      }}
      onKeyDown={(event) => {
        if (event.key === "Enter") event.currentTarget.blur()
      }}
      className="mb-2 h-auto border-transparent px-1.5 py-1 text-2xl font-semibold shadow-none hover:border-input focus-visible:border-ring md:text-2xl dark:bg-transparent"
    />
  )
}

/**
 * A page of text and collection blocks. Opening a record replaces the page with that record until it is closed;
 * closing restores the scroll position and puts focus back on the row that was opened.
 * The app owns storage: `page` and `records` are controlled, and rejected writes are shown as a toast.
 * Leave `openId` undefined to let the component track the open record itself.
 */
export function DocCollections<T extends DocRecord>({
  page,
  onPageChange,
  records,
  onAdd,
  onUpdate,
  onRemove,
  openId,
  onOpenChange,
}: {
  page: DocPage
  onPageChange: (page: DocPage) => void
  records: T[]
  onAdd: (collectionId: string) => Promise<T>
  onUpdate: (id: string, patch: Partial<T>) => Promise<void>
  onRemove: (id: string) => Promise<void>
  openId?: string | null
  onOpenChange?: (id: string | null) => void
}) {
  const [ownOpenId, setOwnOpenId] = useState<string | null>(null)
  const [selection, setSelection] = useState<Record<string, string>>({})
  const currentId = openId === undefined ? ownOpenId : openId
  const open = currentId === null ? undefined : records.find((record) => record.id === currentId)

  const rootRef = useRef<HTMLDivElement>(null)
  const saved = useRef<{ element: HTMLElement; top: number } | null>(null)
  const lastOpened = useRef<{ collectionId: string; id: string } | null>(null)
  const focusTitleFor = useRef<string | null>(null)
  const wasOpen = useRef(false)

  const setOpen = (id: string | null) => {
    if (openId === undefined) setOwnOpenId(id)
    onOpenChange?.(id)
  }

  const openRecord = (collectionId: string, id: string) => {
    const element = scrollParentOf(rootRef.current)
    saved.current = element ? { element, top: element.scrollTop } : null
    setSelection((current) => ({ ...current, [collectionId]: id }))
    setOpen(id)
  }

  const addRecord = async (collectionId: string) => {
    try {
      const created = await onAdd(collectionId)
      focusTitleFor.current = created.id
      openRecord(collectionId, created.id)
    } catch (cause) {
      reportSaveError(cause)
    }
  }

  const updateOpen = async (patch: Partial<T>) => {
    if (!open) return
    try {
      await onUpdate(open.id, patch)
    } catch (cause) {
      reportSaveError(cause)
      throw cause
    }
  }

  const removeOpen = async () => {
    if (!open) return
    try {
      await onRemove(open.id)
      setOpen(null)
    } catch (cause) {
      reportSaveError(cause)
    }
  }

  const openDef = open ? page.collections.find((def) => def.id === open.collectionId) : undefined
  const isOpen = open !== undefined && openDef !== undefined
  useLayoutEffect(() => {
    if (isOpen && !wasOpen.current && saved.current) saved.current.element.scrollTop = 0
    if (!isOpen && wasOpen.current) {
      if (saved.current) saved.current.element.scrollTop = saved.current.top
      const last = lastOpened.current
      if (last) {
        rootRef.current
          ?.querySelector<HTMLElement>(`[data-collection-id="${CSS.escape(last.collectionId)}"]`)
          ?.focus({ preventScroll: true })
      }
    }
    wasOpen.current = isOpen
  }, [isOpen])

  useEffect(() => {
    if (!open) return
    lastOpened.current = { collectionId: open.collectionId, id: open.id }
    if (focusTitleFor.current === open.id) {
      focusTitleFor.current = null
      const title = rootRef.current?.querySelector<HTMLTextAreaElement>("[data-record-title]")
      title?.focus()
      title?.select()
    }
  }, [open])

  const patchBlocks = (blocks: DocPage["blocks"]) => onPageChange({ ...page, blocks })

  const addText = () => patchBlocks([...page.blocks, { id: crypto.randomUUID(), kind: "text", text: "" }])

  const addCollection = () => {
    const collectionId = crypto.randomUUID()
    onPageChange({
      ...page,
      collections: [
        ...page.collections,
        {
          id: collectionId,
          name: `Collection ${page.collections.length + 1}`,
          fields: [{ key: "notes", label: "Notes", type: "text" }],
        },
      ],
      blocks: [...page.blocks, { id: crypto.randomUUID(), kind: "collection", collectionId }],
    })
  }

  return (
    <div ref={rootRef}>
      {open && openDef ? (
        <>
          <RecordPage
            record={open}
            fields={openDef.fields}
            onUpdate={updateOpen}
            onClose={() => setOpen(null)}
            trail={[page.title, openDef.name, open.title]}
          />
          <div className={columnClass}>
            <Button variant="ghost" size="sm" onClick={removeOpen} className="text-muted-foreground">
              <Trash2Icon aria-hidden /> Delete record
            </Button>
          </div>
        </>
      ) : (
        <>
          <Breadcrumb trail={[page.title]} />
          <div className={`${columnClass} py-6`}>
            <PageTitle title={page.title} onCommit={(title) => onPageChange({ ...page, title })} />
            {page.blocks.length === 0 ? (
              <EmptyState
                title="Empty page"
                description="Add some text, or a collection of records."
                action={
                  <div className="flex gap-2">
                    <Button size="sm" onClick={addText}>
                      <PlusIcon aria-hidden /> Add text
                    </Button>
                    <Button size="sm" variant="outline" onClick={addCollection}>
                      <PlusIcon aria-hidden /> Add collection
                    </Button>
                  </div>
                }
              />
            ) : (
              <>
                {page.blocks.map((block) => {
                  if (block.kind === "text") {
                    return (
                      <TextBlock
                        key={block.id}
                        text={block.text}
                        onCommit={(text) =>
                          patchBlocks(page.blocks.map((b) => (b.id === block.id ? { ...block, text } : b)))
                        }
                      />
                    )
                  }
                  const def = page.collections.find((c) => c.id === block.collectionId)
                  if (!def) return null
                  return (
                    <CollectionBlock
                      key={block.id}
                      def={def}
                      records={records.filter((record) => record.collectionId === def.id)}
                      selectedId={selection[def.id]}
                      onSelect={(id) => setSelection((current) => ({ ...current, [def.id]: id }))}
                      onOpen={(id) => openRecord(def.id, id)}
                      onAdd={() => void addRecord(def.id)}
                    />
                  )
                })}
                <div className="mt-4 flex gap-2">
                  <Button variant="ghost" size="sm" onClick={addText}>
                    <PlusIcon aria-hidden /> Add text
                  </Button>
                  <Button variant="ghost" size="sm" onClick={addCollection}>
                    <PlusIcon aria-hidden /> Add collection
                  </Button>
                </div>
              </>
            )}
          </div>
        </>
      )}
    </div>
  )
}

import { useState } from "react"

import { Badge } from "@/components/ui/badge"
import { Checkbox } from "@/components/ui/checkbox"
import { Command, CommandEmpty, CommandInput, CommandItem, CommandList } from "@/components/ui/command"
import { Input } from "@/components/ui/input"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"
import { cn } from "@/lib/utils"

import type { FieldDef, PropValue } from "./types"
import { useDraft } from "./use-draft"

const slot = "h-7 w-full justify-start rounded-md border-transparent bg-transparent px-1.5 text-sm shadow-none hover:bg-muted dark:bg-transparent"

function toText(value: PropValue) {
  return value === null ? "" : String(value)
}

function fromText(field: FieldDef, text: string): PropValue {
  if (text.trim() === "") return null
  if (field.type !== "number") return text
  const n = Number(text)
  return Number.isFinite(n) ? n : null
}

function SelectValue({ field, value, onChange }: { field: FieldDef; value: PropValue; onChange: (value: PropValue) => void }) {
  const [open, setOpen] = useState(false)
  const pick = (next: PropValue) => {
    setOpen(false)
    if (next !== value) onChange(next)
  }

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label={field.label}
          className={cn(slot, "inline-flex items-center rounded-md outline-none focus-visible:ring-3 focus-visible:ring-ring/50")}
        >
          {value === null ? (
            <span className="text-muted-foreground">Empty</span>
          ) : (
            <Badge variant="secondary">{String(value)}</Badge>
          )}
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-56 p-0">
        <Command>
          <CommandInput placeholder={`Find ${field.label.toLowerCase()}`} aria-label={`Find ${field.label}`} />
          <CommandList>
            <CommandEmpty>No options</CommandEmpty>
            {(field.options ?? []).map((option) => (
              <CommandItem key={option} value={option} data-checked={option === value} onSelect={() => pick(option)}>
                {option}
              </CommandItem>
            ))}
            {value === null ? null : (
              <CommandItem value="clear selection" onSelect={() => pick(null)}>
                <span className="text-muted-foreground">Clear</span>
              </CommandItem>
            )}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

function TypedValue({ field, value, onChange }: { field: FieldDef; value: PropValue; onChange: (value: PropValue) => void }) {
  const [draft, setDraft] = useDraft(toText(value))
  const [focused, setFocused] = useState(false)

  const commit = () => {
    const next = fromText(field, draft)
    if (next !== value) onChange(next)
    else setDraft(toText(value))
  }

  // an empty date shows the grey "Empty" placeholder until it is focused
  const type = field.type === "date" ? (draft !== "" || focused ? "date" : "text") : field.type === "url" ? "url" : field.type

  return (
    <Input
      type={type}
      aria-label={field.label}
      placeholder="Empty"
      value={draft}
      onChange={(event) => setDraft(event.target.value)}
      onFocus={() => setFocused(true)}
      onBlur={() => {
        setFocused(false)
        commit()
      }}
      onKeyDown={(event) => {
        if (event.key === "Enter") event.currentTarget.blur()
      }}
      className={cn(slot, "md:text-sm", field.type === "number" && "text-left")}
    />
  )
}

/** Editor for one property value; select applies on pick, text-like types apply on Enter or blur. */
export function PropertyValue({
  field,
  value,
  onChange,
}: {
  field: FieldDef
  value: PropValue
  onChange: (value: PropValue) => void
}) {
  if (field.type === "checkbox") {
    return (
      <div className="flex h-7 items-center px-1.5">
        <Checkbox aria-label={field.label} checked={value === true} onCheckedChange={(checked) => onChange(checked === true)} />
      </div>
    )
  }
  if (field.type === "select") return <SelectValue field={field} value={value} onChange={onChange} />
  return <TypedValue field={field} value={value} onChange={onChange} />
}

import { useCallback, useEffect, useRef, useState } from "react"
import { useHotkeys } from "react-hotkeys-hook"

import { Separator } from "@/components/ui/separator"
import { Textarea } from "@/components/ui/textarea"

import { Breadcrumb } from "./breadcrumb"
import { columnClass } from "./column"
import { PropertyValue } from "./property-value"
import type { DocRecord, FieldDef, PropValue } from "./types"
import { useDraft } from "./use-draft"

const EDITABLE = "input, textarea, select, [contenteditable]"

/**
 * A record opened as a page: title, one editable row per field, then the free-text body.
 * Esc blurs the field being edited first, and closes the record when nothing is being edited.
 * A rejected `onUpdate` puts the edited field back to the stored value.
 */
export function RecordPage<T extends DocRecord>({
  record,
  fields,
  onUpdate,
  onClose,
  trail,
}: {
  record: T
  fields: FieldDef[]
  onUpdate: (patch: Partial<T>) => Promise<void>
  onClose: () => void
  trail: string[]
}) {
  const [revision, setRevision] = useState(0)
  const [title, setTitle] = useDraft(record.title)
  const [body, setBody] = useDraft(record.body)

  // props lag behind edits until each store write resolves, so writes compose from this buffer
  const latestProps = useRef<{ id: string; props: Record<string, PropValue>; pending: number } | null>(null)

  const save = (patch: Partial<T>) => {
    onUpdate(patch).catch(() => {
      setRevision((n) => n + 1)
      setTitle(record.title)
      setBody(record.body)
    })
  }

  const containerRef = useRef<HTMLDivElement | null>(null)
  const hotkeysRef = useHotkeys<HTMLDivElement>(
    "esc",
    () => {
      const active = document.activeElement
      if (active instanceof HTMLElement && active !== containerRef.current && active.matches(EDITABLE)) {
        active.blur()
        containerRef.current?.focus({ preventScroll: true })
        return
      }
      onClose()
    },
    { enableOnFormTags: true, enableOnContentEditable: true }
  )
  const setContainer = useCallback(
    (element: HTMLDivElement | null) => {
      containerRef.current = element
      hotkeysRef(element)
    },
    [hotkeysRef]
  )

  useEffect(() => {
    const container = containerRef.current
    if (container && !container.contains(document.activeElement)) container.focus({ preventScroll: true })
  }, [record.id])

  const commitTitle = () => {
    const next = title.trim()
    if (next === "" || next === record.title) setTitle(record.title)
    else save({ title: next } as Partial<T>)
  }

  const setProp = (key: string, value: PropValue) => {
    const current = latestProps.current?.id === record.id ? latestProps.current : null
    const inFlight = current !== null && current.pending > 0
    const base = inFlight ? current.props : record.props
    const previous = base[key] ?? null
    const entry = { id: record.id, props: { ...base, [key]: value }, pending: (inFlight ? current.pending : 0) + 1 }
    latestProps.current = entry
    onUpdate({ props: entry.props } as Partial<T>)
      .catch(() => {
        setRevision((n) => n + 1)
        const latest = latestProps.current
        if (latest && latest.id === entry.id && latest.props[key] === value) {
          latest.props = { ...latest.props, [key]: previous }
        }
      })
      .finally(() => {
        const latest = latestProps.current
        if (latest && latest.id === entry.id) latest.pending -= 1
      })
  }

  return (
    <div ref={setContainer} tabIndex={-1} role="region" aria-label={`Record: ${record.title}`} className="outline-none">
      <Breadcrumb trail={trail} onNavigate={onClose} />
      <div key={revision} className={`${columnClass} py-6`}>
        <Textarea
          data-record-title
          data-mini="title"
          rows={1}
          aria-label="Title"
          value={title}
          onChange={(event) => setTitle(event.target.value)}
          onBlur={commitTitle}
          onKeyDown={(event) => {
            if (event.key === "Enter") {
              event.preventDefault()
              event.currentTarget.blur()
            }
          }}
          className="min-h-0 resize-none border-transparent px-1.5 text-2xl font-semibold shadow-none md:text-2xl dark:bg-transparent"
        />
        <div className="mt-3 flex flex-col">
          {fields.map((field) => (
            <div key={field.key} className="grid min-h-[26px] grid-cols-2 items-center gap-2 text-sm">
              <span className="truncate px-1.5 text-muted-foreground">{field.label}</span>
              <PropertyValue field={field} value={record.props[field.key] ?? null} onChange={(value) => setProp(field.key, value)} />
            </div>
          ))}
        </div>
        <Separator className="my-4" />
        <Textarea
          aria-label="Body"
          placeholder="Write something"
          value={body}
          onChange={(event) => setBody(event.target.value)}
          onBlur={() => {
            if (body === record.body) return
            save({ body } as Partial<T>)
          }}
          className="min-h-48 border-transparent px-1.5 shadow-none dark:bg-transparent"
        />
      </div>
    </div>
  )
}

export type PropValue = string | number | boolean | null

export type FieldDef = {
  key: string
  label: string
  type: "text" | "number" | "checkbox" | "date" | "url" | "select"
  options?: string[]
}

export type DocRecord = {
  id: string
  title: string
  collectionId: string
  props: Record<string, PropValue>
  body: string
}

export type CollectionDef = { id: string; name: string; fields: FieldDef[] }

export type DocBlock =
  | { id: string; kind: "text"; text: string }
  | { id: string; kind: "collection"; collectionId: string }

export type DocPage = {
  id: string
  title: string
  blocks: DocBlock[]
  collections: CollectionDef[]
}

import { useState } from "react"

/** Local edit buffer for a committed value; it resets whenever the committed value changes. */
export function useDraft(value: string) {
  const [draft, setDraft] = useState(value)
  const [seen, setSeen] = useState(value)
  if (seen !== value) {
    setSeen(value)
    setDraft(value)
  }
  return [draft, setDraft] as const
}
